package solution

import (
	"errors"
	"sort"
	"strconv"
	"time"
)

type AssetRecord struct {
	ID         string
	Labels     []string
	Owner      string
	Created    string
	Modified   string
	Attributes map[string][]string
}

type AssetQuery struct {
	Owner            string
	Label            string
	CreatedOnOrAfter time.Time
	PageSize         int
	Cursor           string
}

type AssetRow struct {
	ID         string
	Labels     []string
	Owner      string
	Created    time.Time
	Modified   time.Time
	Attributes map[string][]string
}

func ListAssets(records []AssetRecord, query AssetQuery) ([]AssetRow, string, error) {
	if query.PageSize <= 0 {
		return nil, "", errors.New("page size must be positive")
	}
	seen := make(map[string]bool, len(records))
	rows := make([]AssetRow, 0)
	for _, record := range records {
		if record.ID == "" || seen[record.ID] {
			return nil, "", errors.New("asset IDs must be non-empty and unique")
		}
		seen[record.ID] = true
		created, err := time.Parse(time.RFC3339, record.Created)
		if err != nil {
			return nil, "", err
		}
		modified, err := time.Parse(time.RFC3339, record.Modified)
		if err != nil {
			return nil, "", err
		}
		if query.Owner != "" && record.Owner != query.Owner {
			continue
		}
		if query.Label != "" && !containsLabel(record.Labels, query.Label) {
			continue
		}
		if !query.CreatedOnOrAfter.IsZero() && created.Before(query.CreatedOnOrAfter) {
			continue
		}
		rows = append(rows, AssetRow{
			ID:         record.ID,
			Labels:     append([]string(nil), record.Labels...),
			Owner:      record.Owner,
			Created:    created,
			Modified:   modified,
			Attributes: cloneAttributes(record.Attributes),
		})
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].ID < rows[j].ID })
	offset, err := parseCursor(query.Cursor)
	if err != nil || offset > len(rows) {
		return nil, "", errors.New("invalid cursor")
	}
	remaining := len(rows) - offset
	pageLength := query.PageSize
	if pageLength > remaining {
		pageLength = remaining
	}
	end := offset + pageLength
	page := rows[offset:end]
	next := ""
	if end < len(rows) {
		next = strconv.Itoa(end)
	}
	return page, next, nil
}

func containsLabel(labels []string, wanted string) bool {
	for _, label := range labels {
		if label == wanted {
			return true
		}
	}
	return false
}

func parseCursor(cursor string) (int, error) {
	if cursor == "" {
		return 0, nil
	}
	if cursor != "0" && cursor[0] == '0' {
		return 0, errors.New("non-canonical cursor")
	}
	for _, character := range cursor {
		if character < '0' || character > '9' {
			return 0, errors.New("invalid cursor")
		}
	}
	value, err := strconv.Atoi(cursor)
	if err != nil {
		return 0, err
	}
	return value, nil
}

func cloneAttributes(source map[string][]string) map[string][]string {
	if source == nil {
		return nil
	}
	copy := make(map[string][]string, len(source))
	for key, values := range source {
		copy[key] = append([]string(nil), values...)
	}
	return copy
}
